nextflow_process {

    name "Test Process RSEQC_JUNCTIONANNOTATION"
    script "../main.nf"
    process "RSEQC_JUNCTIONANNOTATION"

    tag "modules"
    tag "modules_nfcore"
    tag "rseqc"
    tag "rseqc/junctionannotation"

    test("sarscov2 - paired end [bam]") {

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test', single_end: false ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai", checkIfExists: true)
                ])
                input[1] = channel.of(file(params.modules_testdata_base_path + "genomics/sarscov2/genome/bed/test.bed12", checkIfExists: true))
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.pdf.size() == 0 || file(process.out.pdf[0][1]).name.endsWith('.pdf') },
                { assert process.out.events_pdf.size() == 0 || file(process.out.events_pdf[0][1]).name.endsWith('.pdf') },
                { assert process.out.xls.size() == 0 || file(process.out.xls[0][1]).name.endsWith('.xls') },
                { assert process.out.rscript.size() == 0 || file(process.out.rscript[0][1]).name.endsWith('.r') },
                { assert snapshot(
                    process.out.log,
                    process.out.versions_rseqc
                ).match() }
            )
        }
    }

    test("sarscov2 - paired end [bam] - stub") {

    options "-stub"

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test', single_end: false ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai", checkIfExists: true)
                ])
                input[1] = channel.of(file(params.modules_testdata_base_path + "genomics/sarscov2/genome/bed/test.bed12", checkIfExists: true))
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() },
                { assert snapshot(process.out.versions_rseqc).match("versions") }
            )
        }
    }
}

